//! ArmourType: ARMOUR "material type" (sheet T00032).
//!
//! Generated by `python tools/gen_enum.py T00032 ArmourType ...` from sheet/enums.tsv; do not edit.

/// @type ArmourType
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(i32)]
pub enum ArmourType {
    Cloth = 0,
    Leather = 1,
    Chain = 2,
    MetalPlate = 3,
}

impl ArmourType {
    pub fn from_i32(v: i32) -> Option<Self> {
        Some(match v {
            0 => Self::Cloth,
            1 => Self::Leather,
            2 => Self::Chain,
            3 => Self::MetalPlate,
            _ => return None,
        })
    }

    /// The name as in the sheet (the FCS schema name).
    pub fn name(self) -> &'static str {
        match self {
            Self::Cloth => "CLOTH",
            Self::Leather => "LEATHER",
            Self::Chain => "CHAIN",
            Self::MetalPlate => "METAL_PLATE",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_sheet() {
        let sheet = include_str!("../../sheet/enums.tsv");
        let mut n = 0;
        for line in sheet.lines().filter(|l| l.starts_with("T00032\t")) {
            let f: Vec<&str> = line.split('\t').collect();
            let v: i32 = f[2].parse().unwrap();
            let t = ArmourType::from_i32(v)
                .unwrap_or_else(|| panic!("sheet value {v} missing in enum"));
            assert_eq!(t.name(), f[1]);
            assert_eq!(t as i32, v);
            n += 1;
        }
        assert_eq!(n, 4, "enum and sheet differ in size");
    }
}
